    const wide: u256 = (@as(u256, hi) << 128) | lo;
    const x: u3 = @bitCast(@as(u3, @truncate(wide)));
    const amt: u2 = @intCast(k);
    return switch (sel) {
        0 => @as(u128, @clz(x)),
        1 => @as(u128, @ctz(x)),
        2 => @as(u128, @popCount(x)),
        3 => @as(u128, @truncate(@as(u256, @as(u3, @bitCast(x << amt))))),
        5 => @as(u128, @truncate(@as(u256, @as(u3, @bitCast(@shlWithOverflow(x, amt)[0]))))),
        6 => @as(u128, @truncate(@as(u256, @as(u3, @bitCast(x >> amt))))),
        8 => @as(u128, @truncate(@as(u256, @as(u3, @bitCast(@bitReverse(x)))))),
        4 => @as(u128, @shlWithOverflow(x, amt)[1]),
        else => 0,
    };
}

