    const amt: u8 = @intCast(k);
    return switch (sel) {
        0 => @as(u128, @clz(x)),
        1 => @as(u128, @ctz(x)),
        2 => @as(u128, @popCount(x)),
        3 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x << amt))))),
        19 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x << amt))) >> 128)),
        5 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@shlWithOverflow(x, amt)[0]))))),
        21 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@shlWithOverflow(x, amt)[0]))) >> 128)),
        6 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x >> amt))))),
        22 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x >> amt))) >> 128)),
        8 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@bitReverse(x)))))),
        24 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@bitReverse(x)))) >> 128)),
        7 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@byteSwap(x)))))),
        23 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@byteSwap(x)))) >> 128)),
        4 => @as(u128, @shlWithOverflow(x, amt)[1]),
        else => 0,
    };
}

pub export fn ops_i200(sel: u32, hi: u128, lo: u128, k: u32) u128 {
    @setRuntimeSafety(false); // counts >= W are excluded; the checked panic path is not translated
    const wide: u256 = (@as(u256, hi) << 128) | lo;
    const x: i200 = @bitCast(@as(u200, @truncate(wide)));
    const amt: u8 = @intCast(k);
    return switch (sel) {
        0 => @as(u128, @clz(x)),
        1 => @as(u128, @ctz(x)),
        2 => @as(u128, @popCount(x)),
        3 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x << amt))))),
        19 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x << amt))) >> 128)),
        5 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@shlWithOverflow(x, amt)[0]))))),
        21 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@shlWithOverflow(x, amt)[0]))) >> 128)),
        6 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x >> amt))))),
        22 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(x >> amt))) >> 128)),
        8 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@bitReverse(x)))))),
        24 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@bitReverse(x)))) >> 128)),
        7 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@byteSwap(x)))))),
        23 => @as(u128, @truncate(@as(u256, @as(u200, @bitCast(@byteSwap(x)))) >> 128)),
        4 => @as(u128, @shlWithOverflow(x, amt)[1]),
        else => 0,
    };
}
